SELECT id, product_id, price, record_date, created_at
FROM price_records
WHERE product_id = #{productId}
AND record_date = #{recordDate}
LIMIT 1

SELECT id, product_id, price, record_date, created_at
FROM price_records


        AND product_id = #{productId}


        AND record_date >= #{startDate}


        AND record_date <= #{endDate}


ORDER BY record_date DESC

SELECT AVG(price)
FROM price_records
WHERE product_id = #{productId}
